/**
 * anim-registry.js — W.H. Academy · Animation Lab catalogue
 * ----------------------------------------------------------------------------
 * The list of animations the Animations tab can show. SAME shape as
 * content-registry.js (classes → subject key → chapters) so scope.js can gate
 * it with the very same call:  WHA_Scope.allowedSubjects(scope, WHA_ANIMS).
 *
 * To add an animation:
 *   1. put its spec at  games/anim-data/<board>/<class>/<subject>/<chapter>/<key>.json
 *      <board> = apsacs (class 6-8) | federal (class 9-12) | kpk | punjab | olevel  (see REPO_MAP.md)
 *   2. add one entry below under the right class → subject → chapter
 *   3. bump CACHE_VERSION in sw.js and deploy
 *
 * Entry fields:
 *   id       unique, never changes (it is the key the student's saved values use)
 *   title    card title                      topic   short topic line
 *   summary  one sentence on the card        file    path of the JSON spec (relative to /games/)
 *   minutes  rough lesson length             level   "Starter" | "Core" | "Challenge"
 *   icon     optional emoji
 *
 * Optional — chapters that follow a textbook (Theory · 7.1 · 7.2 · 7.3 …):
 *   chapter.sections  [{ key, label, title }]  → the hub shows these as tabs
 *   entry.section     which tab the entry lives under ("theory" or a section key)
 *   entry.group       sub-heading inside the tab (e.g. "Worked Examples", "Exercise 7A")
 *   entry.label       short chip shown on the row (e.g. "Worked Example 1", "Exercise 7A · Q3(b)")
 *   entry.question    the textbook question; shown on the row and above the player
 *   A chapter without `sections` is shown as the plain card grid, exactly as before.
 * ----------------------------------------------------------------------------
 */
